"""Write the ledger schema the TypeScript capture package creates files with.

    python scripts/export_ts_schema.py

``tests/test_ts_compat.py`` fails if ts/src/schema.ts is out of date.
"""

import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))

from dod.ledger import _SCHEMA, SCHEMA_VERSION  # noqa: E402

OUT = Path(__file__).resolve().parents[1] / "ts" / "src" / "schema.ts"


def render() -> str:
    return (
        "// Generated by scripts/export_ts_schema.py from dod.ledger. Do not edit.\n"
        f"export const SCHEMA_VERSION = {SCHEMA_VERSION};\n"
        f"export const SCHEMA = {json.dumps(_SCHEMA)};\n"
    )


if __name__ == "__main__":
    OUT.write_text(render())
    print(f"wrote {OUT}")
